#!/usr/bin/env python3
from Crypto.Cipher import AES
import gmpy2

def try_decrypt(key, enc_data, iv):
    try:
        cipher = AES.new(key, AES.MODE_CBC, iv=iv)
        dec = cipher.decrypt(enc_data)
        if dec.startswith(b'\x89PNG\r\n\x1a\n'):
            return dec
    except:
        pass
    return None

def geometric_sequence_sum(base, count):
    # Calculates sum of geometric sequence: base * (1 + 2 + 4 + 8 + ...)
    return base * ((1 << count) - 1)

def generate_key(input_val):
    # Break input into bytes
    bytes_list = [int(input_val >> (8 * i) & 0xFF) for i in range(7, -1, -1)]

    # For each byte, generate geometric sequence
    result = 0
    for i, byte in enumerate(bytes_list):
        if byte:
            # Generate geometric sequence starting from this byte position
            result += geometric_sequence_sum(byte, 8-i)

    # Convert to 32 bytes (big-endian)
    return result.to_bytes(32, 'big')

def main():
    input_val = 0xcafed3adb3ef1e37
    iv = b"r4nd0m_1v_ch053n"

    with open('ctf_files/flag.enc', 'rb') as f:
        enc_data = f.read()

    key = generate_key(input_val)
    dec = try_decrypt(key, enc_data, iv)

